var grid = $($(".component[name=FundingMappingManagement]").children()[4]).data("kendoGrid");
var dmsData = JSON.parse(await api.get("DMS/Data/Transactions/fundingMappings.json"));
for (var i = 0; i < k.length; i = i + 1) {
    grid.dataSource.insert(0, {
        Reference: k[i].BuyerCompanyCode + "_" + k[i].SupplierCompanyCode,
        Formula: dmsData.filter(r => r.Reference == k[i].DiscountCode)[0].Formula
    });
}
